import { Component, input, signal } from '@angular/core';
import { email, form, max, maxLength, min, minLength, pattern, required } from '@angular/forms/signals';
import { JSONValue } from '@ng-vagabond-lab/ng-dsv/api';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import { DsvFormSignalCheckboxComponent } from '../../checkbox/component/form-signal-checkbox.component';
import { DsvFormSignalInputComponent } from '../../public-api';
import { DsvFormSignalSelectComponent } from '../../select/component/form-signal-select.component';
import { DsvFormSignalComponent } from './form-signal.component';

export const ActionsData = {
    urlBack: '/',
};

@Component({
    selector: 'storybook-wrapper',
    standalone: true,
    imports: [
        DsvFormSignalComponent,
        DsvFormSignalInputComponent,
        DsvFormSignalSelectComponent,
        DsvFormSignalCheckboxComponent,
    ],
    template: `
        <dsv-form-signal [form]="myForm" [urlBack]="urlBack()" (callback)="callback($event)">
            <dsv-form-signal-input [form]="myForm" fieldName="name" />
            <dsv-form-signal-input [form]="myForm" type="email" fieldName="email" />
            <dsv-form-signal-input [form]="myForm" type="number" fieldName="number" />
            <dsv-form-signal-input [form]="myForm" type="range" fieldName="range" />
            <dsv-form-signal-input [form]="myForm" type="datetime-local" fieldName="date" />
            <dsv-form-signal-input [form]="myForm" type="textarea" fieldName="textarea" />
            <dsv-form-signal-select
                [form]="myForm"
                fieldName="select"
                [list]="[
                    { id: '', name: '' },
                    { id: '1', name: 'Test' },
                ]"
            />
            <dsv-form-signal-checkbox [form]="myForm" fieldName="checkbox" />
        </dsv-form-signal>
    `,
    styles: [
        `
            :host {
                width: 100%;
            }
        `,
    ],
})
class FormSignalWrapperComponent {
    myForm = form(
        signal({
            name: '',
            email: '',
            number: 0,
            range: 50,
            date: '',
            textarea: '',
            select: '',
            checkbox: false,
        }),
        (path) => {
            required(path.name);
            minLength(path.name, 2);
            maxLength(path.name, 10);
            required(path.email);
            pattern(path.email, /^\w+@gmail.com$/, { message: "L'email doit se terminer par gmail.com" });
            email(path.email);
            required(path.textarea);
            required(path.select);

            min(path.number, 1);
            max(path.number, 5);
        },
    );

    urlBack = input<string>('/');

    callback = (data: JSONValue) => {
        console.log(data);
    };
}

const meta: Meta<FormSignalWrapperComponent> = {
    title: 'dsv/Form/Signal',
    component: FormSignalWrapperComponent,
    excludeStories: /.*Data$/,
    tags: ['autodocs'],
    parameters: {
        controls: { exclude: ['form'] },
    },
    decorators: [moduleMetadata({})],
    argTypes: {},
    args: {
        ...ActionsData,
    },
};

export default meta;
type Story = StoryObj<FormSignalWrapperComponent>;

export const Default: Story = {
    args: {
        urlBack: '/',
    },
    parameters: {
        docs: {
            source: {
                code: `
          <dsv-form-signal [form]="myForm" [urlBack]="urlBack()" (callback)="callback($event)">
            <dsv-form-signal-input [form]="myForm" fieldName="name" />
            <dsv-form-signal-input [form]="myForm" type="email" fieldName="email" />
            <dsv-form-signal-input [form]="myForm" type="number" fieldName="number" />
            <dsv-form-signal-input [form]="myForm" type="range" fieldName="range" />
            <dsv-form-signal-input [form]="myForm" type="datetime-local" fieldName="date" />
            <dsv-form-signal-input [form]="myForm" type="textarea" fieldName="textarea" />
            <dsv-form-signal-select [form]="myForm" fieldName="select" [list]="[{id: '', name: ''}, {id: '1', name: 'Test'}]" />
            <dsv-form-signal-checkbox [form]="myForm" fieldName="checkbox" />
          </dsv-form-signal>


          class FormComponent {
            myForm = form(signal({
              name: '',
              email: '',
              number: 0,
              range: 50,
              date: '',
              textarea: '',
              select: '',
              checkbox: false,
            }), path => {
              required(path.name);
              minLength(path.name, 2);
              maxLength(path.name, 10);
              required(path.email);
              pattern(path.email, /^\w+@gmail.com$/, { message: "L'email doit se terminer par gmail.com" });
              email(path.email);
              required(path.textarea);
              required(path.select);
            });

            urlBack = input<string>('/');

            callback = (data: JSONValue) => {
              console.log(data);
            }
          }
        `,
            },
        },
    },
};

import { Component } from '@angular/core';
import { DsvCardComponent } from '@ng-vagabond-lab/ng-dsv/ds/card';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import { DsvListItemComponent, DsvListItemDragComponent } from '../../public-api';
import { ListItemDragDto } from '../dto/list.dto';
import { DsvListComponent } from './list.component';

export const ActionsData = {};

@Component({
    selector: 'app-list-wrapper',
    standalone: true,
    imports: [DsvCardComponent, DsvListComponent, DsvListItemComponent, DsvListItemDragComponent],
    template: `
        <dsv-card>
            <dsv-list>
                @for (element of elements; track element; let index = $index) {
                    <dsv-list-item [index]="index" (callbackOrder)="onDrop($event)">
                        <dsv-list-item-drag />
                        {{ element }}
                    </dsv-list-item>
                }
            </dsv-list>
        </dsv-card>
    `,
    styles: [
        `
            :host {
                width: 100%;
            }
        `,
    ],
})
class ListWrapperComponent {
    elements: string[] = ['Element 1', 'Element 2', 'Element 3', 'Element 4', 'Element 5'];

    onDrop(itemDrag: ListItemDragDto) {
        const list = [...this.elements];
        const moved = list[itemDrag.dragSrcIndex];
        const filtered = list.filter((_, i) => i !== itemDrag.dragSrcIndex);
        filtered.splice(itemDrag.targetIndex, 0, moved);
        this.elements = filtered;
    }
}

const meta: Meta<ListWrapperComponent> = {
    title: 'dsv/List',
    component: ListWrapperComponent,
    excludeStories: /.*Data$/,
    tags: ['autodocs'],
    decorators: [moduleMetadata({})],
    argTypes: {},
    args: {
        ...ActionsData,
    },
};

export default meta;
type Story = StoryObj<ListWrapperComponent>;

export const Default: Story = {
    args: {},
    parameters: {
        docs: {
            source: {
                code: `
                    <dsv-list>
                        @for (element of elements; track element; let index = $index) {
                            <dsv-list-item
                                [index]="index"
                                (callbackOrder)="onDrop($event)"
                            >
                                <dsv-list-item-drag />
                                {{ element }}
                            </dsv-list-item>
                        }
                    </dsv-list>
                `,
            },
        },
    },
};

import { Component } from '@angular/core';
import { componentWrapperDecorator, moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
