@Component({
    selector: 'toast-button-demo',
    imports: [DsvButtonComponent],
    template: `
        <div
            class="flex"
            style="gap: 5px;"
        >
            <dsv-button
                color="success"
                (callback)="click()"
                icon="ri-check-fill"
                libelle="Success"
            ></dsv-button>
            <dsv-button
                color="info"
                (callback)="click('info')"
                icon="ri-information-2-line"
                libelle="Info"
            ></dsv-button>
            <dsv-button
                color="warning"
                (callback)="click('warning')"
                icon="ri-alert-line"
                libelle="Warning"
            ></dsv-button>
            <dsv-button
                color="error"
                (callback)="click('error')"
                icon="ri-close-line"
                libelle="Error"
            ></dsv-button>
        </div>
    `,
})
class PrimaryButtonDemo {
    constructor(private readonly toastService: ToastService) {}

    click(type: ToastType = 'success') {
        this.toastService.showToast({
            text:
                type +
                'je pense que tout doit être visible car sinon cest bad de ouf ' +
                Math.floor(Math.random() * 101),
            type: type,
        });
    }
}

export const Default: Story = {
    args: {},
    decorators: [
        moduleMetadata({
            imports: [PrimaryButtonDemo],
        }),
        componentWrapperDecorator((story) => {
            return `
        <div style="height: 300px"><toast-button-demo />${story}</div>
      `;
        }),
    ],
};

